static void streamzap_callback(struct urb *urb)
{
	struct streamzap_ir *sz;
	int len;

	if (!urb)
		return;

	sz = urb->context;
	len = urb->actual_length;

	switch (urb->status) {
	case 0:
		dev_dbg(sz->dev, "%s: received urb, len %d\n", __func__, len);
